describe('P02 complete snapshot scan before bulk-volume work', () => {
  it('validates all eight records with bounded full inventory passes and unchanged bytes', async () => {
    const { f, j, p } = await begun()
    for (const phase of [
      'VALIDATED',
      'PREPARED',
      'SWAPPED',
      'PRESENTATION_ACK',
      'COMMITTED',
      'CLEANUP',
    ])
      await j.phase(tx, phase)
    const marker = (await j.scan()).records.find((r) => r.record.phase === 'COMMITTED')!
    await j.disposition(tx, {
      outcome: 'RETAINED_COMMITTED',
      authorityHash: marker.sha256,
      registry: p.newRegistry,
      presentation: p.newPresentation,
      consumedRevision: 12,
      cleanupPending: [],
    })
    const before = [...f.files].map(([name, b]) => ({ name, sha: hash(b) })),
      start = f.calls.length
    expect((await new InstallerJournal(f, 2).scan()).records).toHaveLength(8)
    expect(f.calls.slice(start).filter((c) => c.operation === 'list')).toHaveLength(5)
    expect([...f.files].map(([name, b]) => ({ name, sha: hash(b) }))).toEqual(before)
  })
  it('blocks an unknown entry introduced during full scan before returning authority', async () => {
    const { f } = await begun(),
      request = f.request.bind(f)
    let changed = false
    f.request = async (p) => {
      const r = await request(p)
      if (p.operation === 'read' && !changed) {
        changed = true
        f.seed('journal/records/unknown', Buffer.from('preserve'))
      }
      return r
    }
    await expect(new InstallerJournal(f, 2).scan()).rejects.toThrow('RECOVERY_BLOCKED')
    expect(f.files.get('journal/records/unknown')?.toString()).toBe('preserve')
  })
  it('blocks same-byte identity replacement during a full scan', async () => {
    const { f, j } = await begun(),
      name = (await j.scan()).records[0].name,
      request = f.request.bind(f)
    let changed = false
    f.request = async (p) => {
      const r = await request(p)
      if (p.operation === 'read' && !changed) {
        changed = true
        f.identities.set('journal/records/' + name, 'f'.repeat(24))
      }
      return r
    }
    await expect(new InstallerJournal(f, 2).scan()).rejects.toThrow('RECOVERY_BLOCKED')
  })
})

