describe('P02 full admission state validation before journal effects', () => {
  it('publishes held same-parent pending to absent final, links exact prefix hashes and reserves before STAGING', async () => {
    const { f, j, p } = await begun(),
      first: any = (await j.scan()).records[0]
    const old = Buffer.from(f.files.get('journal/records/' + first.name)!)
    await j.phase(tx, 'VALIDATED')
    const scan = await new InstallerJournal(f, 2).scan()
    expect(scan.records).toHaveLength(2)
    expect(scan.records[1].record.previousRecordSHA256).toBe(hash(old))
    expect(scan.records[0].record.payload).toEqual(p)
    expect(scan.remainingSlots).toBe(6)
    expect(scan.remainingBytes).toBe(8388608 - scan.usedBytes)
    expect(f.files.get('journal/records/' + first.name)).toEqual(old)
    const replace = f.calls.find((c) => c.operation === 'replace')
    expect(replace).toMatchObject({ parent: ['journal', 'records'] })
    expect([...f.files.keys()].some((k) => k.includes('.pending-'))).toBe(false)
  })
  it('does not admit a second transaction before the closing disposition', async () => {
