      await j.phase(tx, 'VALIDATED')
      const scan = await j.scan(),
        second = clone(scan.records[1].record)
      f.files.delete('journal/records/' + scan.records[1].name)
      if (attack === 'gap') second.ordinal = 3
      if (attack === 'fork') second.previousRecordSHA256 = 'b'.repeat(64)
      if (attack === 'payload') second.payloadSHA256 = 'b'.repeat(64)
      if (attack === 'transition') second.phase = 'COMMITTED'
      if (attack === 'snapshots') second.payload.newPresentation.selection.density = 'comfortable'
      if (attack === 'revision') second.expectedRegistryRevision = 99
      if (attack !== 'payload') second.payloadSHA256 = hash(canonical(second.payload))
      if (attack === 'noncanonical') {
        const bytes = Buffer.from(JSON.stringify(second, null, 2))
        f.seed(
          'journal/records/' +
            String(second.ordinal).padStart(20, '0') +
            '.' +
            tx +
            '.' +
            hash(bytes) +
            '.json',
          bytes,
        )
      } else seedRecord(f, second)
      await expect(new InstallerJournal(f, 2).scan()).rejects.toThrow('RECOVERY_BLOCKED')
    },
  )
  it('blocks duplicate ordinal even when both file hashes are internally valid', async () => {
