      const { f, j } = await begun()
      for (const p of ['VALIDATED', 'PREPARED', 'SWAPPED', 'PRESENTATION_ACK']) await j.phase(tx, p)
      f.fail = fail
      await expect(j.phase(tx, 'COMMITTED')).rejects.toThrow('JOURNAL_PUBLICATION_UNKNOWN')
      f.state = 'VERIFIED'
      f.fail = null
      const scan = await new InstallerJournal(f, 2).scan()
      expect(scan.authority!.registry).toEqual(
        fail === 'replace-after' ? plan(hash(compatible)).newRegistry : plan().oldRegistry,
      )
      expect(scan.records).toHaveLength(fail === 'replace-after' ? 6 : 5)
      await expect(j.phase(tx, 'COMMITTED')).rejects.toThrow('JOURNAL_SESSION_UNUSABLE')
    },
  )
  it('completes normal seven phases plus one disposition and repeated scan appends nothing', async () => {
